INSERT INTO `templates` (`id`, `title`, `description`, `sections`, `is_active`, `created_by`, `created_by_name`, `created_at`, `updated_at`, `standard_key`) VALUES ('2f2cb6d2-b648-4332-8d29-414fa26e6675','Audit industriel — Usine S2I','Trame standard pour les audits usine : ventes, ordres de fabrication, machines/moules, matières premières, rebuts, recouvrement, RH et sécurité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"7e290de2-eac1-46d4-af95-f38d8db2d145\",\"label\":\"Ventes et chiffre d\'affaires\",\"questions\":[{\"id\":\"5c40c65f-03f7-4326-a856-05ccc8bcf0ea\",\"text\":\"L\'évolution du chiffre d\'affaires du mois est-elle conforme aux objectifs ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"b6112559-5f4a-4c25-8ff6-574a629ea7b9\",\"text\":\"Précisez les écarts constatés et leurs causes (perte de clients, nouveaux clients…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"5c40c65f-03f7-4326-a856-05ccc8bcf0ea\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"0d59f46b-d080-4ce1-8193-3167641a7899\",\"text\":\"Des clients majeurs ont-ils réduit ou arrêté leurs commandes ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"85ebc9c2-2deb-4afe-8d02-812b9f2952ab\",\"text\":\"Précisez les clients concernés et le plan d\'action commercial\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"0d59f46b-d080-4ce1-8193-3167641a7899\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"5a49ffa1-2cac-415d-bc79-477c28335e2e\",\"label\":\"Ordres de fabrication et sorties matière\",\"questions\":[{\"id\":\"a2d3547f-ffc3-404b-9900-98dbd88c4431\",\"text\":\"Les ordres de fabrication et bons de sortie matière première sont-ils tous enregistrés et cohérents ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"f65246a4-36cb-4266-86eb-dd768b83e339\",\"text\":\"Précisez les écarts ou retards de saisie constatés et la cause (absence, surcharge…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a2d3547f-ffc3-404b-9900-98dbd88c4431\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"53d17551-a2eb-4495-a1e5-0466242f269a\",\"label\":\"État des machines et moules\",\"questions\":[{\"id\":\"782eaf12-48d2-444f-907c-6115c0da2850\",\"text\":\"Les machines et moules sont-ils en bon état de fonctionnement ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"b4f24794-bdda-4b6e-a374-30175083cffa\",\"text\":\"Détail des pannes constatées (machine, pièce, durée) et plan d\'action\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"782eaf12-48d2-444f-907c-6115c0da2850\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"12766f97-2be7-481c-b34b-def1c621df71\",\"text\":\"Nombre de machines à l\'arrêt lors de la visite\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false}]},{\"id\":\"6d8cd0d3-ca83-4682-b627-884d859cb119\",\"label\":\"Inventaire matières premières\",\"questions\":[{\"id\":\"14d3d22e-5d13-4367-a980-878c4961d077\",\"text\":\"Le stock physique de matières premières correspond-il aux données système ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"ee201be0-8b01-45d4-b418-b88ca832b3ca\",\"text\":\"Précisez les articles et quantités en écart\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"14d3d22e-5d13-4367-a980-878c4961d077\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"55e885c9-318f-43af-a3a7-fe620cadefeb\",\"label\":\"Rebuts et déchets\",\"questions\":[{\"id\":\"e58d3d71-1250-4799-8a41-8f8e34c1cd34\",\"text\":\"Le taux de rebuts constaté est-il dans la norme attendue ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"df888fd2-da43-4e4b-be18-c26dfbf7390f\",\"text\":\"Taux de rebuts constaté (%)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"e58d3d71-1250-4799-8a41-8f8e34c1cd34\",\"triggerValues\":[\"no\"]}},{\"id\":\"71022509-24be-440f-88eb-8b0e9d49f0c2\",\"text\":\"Le stock de déchets à vendre est-il suivi et écoulé régulièrement ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]},{\"id\":\"a18846e2-241b-401d-b643-a593d6149078\",\"label\":\"Suivi balance client et recouvrement\",\"questions\":[{\"id\":\"5eb68683-0f0b-4a1a-b654-75952345f09f\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"60ed8c02-cd6b-4470-8f60-e0fffe09e3f3\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"22547f3d-6020-42f8-bdb2-3c6ffa6e5cb6\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"5eb68683-0f0b-4a1a-b654-75952345f09f\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"c5b69ad3-3f72-4e48-9514-1a6b321384bb\",\"label\":\"Organisation et climat social\",\"questions\":[{\"id\":\"61ad6418-0fc6-4e65-ba75-dd3ab4217d1c\",\"text\":\"Les effectifs (production, administratif) sont-ils suffisants ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"76bdea78-4562-4b50-ad30-8d5bebb71626\",\"text\":\"Précisez les postes en tension et les recommandations\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"61ad6418-0fc6-4e65-ba75-dd3ab4217d1c\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"382b20a3-60d4-4bfc-935e-9afb48d7585c\",\"text\":\"Un conflit ou climat social tendu a-t-il été observé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"91f2c36f-a6ce-4e57-8acd-909f11a3423f\",\"text\":\"Détail du conflit constaté et mesures recommandées\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"382b20a3-60d4-4bfc-935e-9afb48d7585c\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"9cda42ab-3926-40f7-b504-5f2c9540fbe1\",\"label\":\"Hygiène, sécurité et environnement usine\",\"questions\":[{\"id\":\"82b4a897-7332-418e-8ab6-ac60a5030c3b\",\"text\":\"L\'état de propreté de l\'usine est-il satisfaisant ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true},{\"id\":\"aab91c13-4571-4975-8ac2-c5b6eb171372\",\"text\":\"Les équipements de sécurité (extincteurs, caméras) sont-ils opérationnels et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"9cbf9f3c-07a3-4084-aac4-5e0dab2456e4\",\"text\":\"Précisez les anomalies constatées et les actions correctives\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"aab91c13-4571-4975-8ac2-c5b6eb171372\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"8c3ef199-3237-4694-9e9c-d76dd240fddf\",\"text\":\"Le matériel informatique (postes, imprimantes) est-il suffisant et fonctionnel ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T14:49:10.335Z','2026-10-21T14:49:10.335Z','usine'),
('68afdfcd-0c3f-48b4-b21a-18a67b94a75f','Audit logistique — Déchargement de containers importés','Grille de contrôle standard pour le déchargement des containers importés : contrôle documentaire avant ouverture, inspection de l\'état général, comptage contradictoire et DLC, procédure en cas de non-conformité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"f8835845-3330-4779-81cf-c233c1e23eee\",\"label\":\"Contrôle documentaire (avant ouverture)\",\"questions\":[{\"id\":\"c8007c8f-470f-4597-8231-a7a8b17bc506\",\"text\":\"Le Bill of Lading est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"3ef229e3-ee83-43ed-8d18-95114d6d0c2b\",\"text\":\"Précisez l\'anomalie constatée sur le Bill of Lading\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"c8007c8f-470f-4597-8231-a7a8b17bc506\",\"triggerValues\":[\"no\"]}},{\"id\":\"1825549b-e7fe-46d1-8317-4d2c738983e8\",\"text\":\"Le certificat sanitaire est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"6675d32e-dac5-428a-8e11-b46dbd2ceb2e\",\"text\":\"Précisez l\'anomalie constatée sur le certificat sanitaire\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"1825549b-e7fe-46d1-8317-4d2c738983e8\",\"triggerValues\":[\"no\"]}},{\"id\":\"383edbb5-b0c1-417e-837a-bfb658d60cbe\",\"text\":\"Le certificat d\'origine est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"eba2b846-61bb-43f6-a525-ea431e76ed35\",\"text\":\"Précisez l\'anomalie constatée sur le certificat d\'origine\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"383edbb5-b0c1-417e-837a-bfb658d60cbe\",\"triggerValues\":[\"no\"]}},{\"id\":\"a65f7651-5408-4a27-ba1d-1832be3ccba3\",\"text\":\"Le Packing List est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"544da359-02b2-45d3-9fca-442a44862dd2\",\"text\":\"Précisez l\'anomalie constatée sur le Packing List\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a65f7651-5408-4a27-ba1d-1832be3ccba3\",\"triggerValues\":[\"no\"]}},{\"id\":\"203ac618-cce4-483d-a8e2-b55b8f00294d\",\"text\":\"Autres documents contrôlés (facture, etc.) — précisez lesquels et leur conformité\",\"type\":\"TEXT\",\"weight\":1,\"required\":false},{\"id\":\"17f4e665-33b5-4c22-bccc-14489ce0916e\",\"text\":\"Existe-t-il un plombage identifiable et numéroté ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"4abc86d2-d1f4-47d9-bf15-434c15c26a63\",\"text\":\"Précisez l\'anomalie constatée (absence de plombage, numéro illisible…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"17f4e665-33b5-4c22-bccc-14489ce0916e\",\"triggerValues\":[\"no\"]}},{\"id\":\"07d14523-2d8b-4578-9324-1a55947f02e2\",\"text\":\"Numéro du plombage relevé\",\"type\":\"TEXT\",\"weight\":1,\"required\":false}]},{\"id\":\"f9cf1ad9-ceab-4f0d-badc-f5099046fe02\",\"label\":\"Inspection de l\'état général du container\",\"questions\":[{\"id\":\"078cf50c-13a7-481e-baa5-1d82cf96c73e\",\"text\":\"Le container est-il intact (absence d\'ouvertures ou de fuites) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"9a360a76-e266-4ad5-877c-bb5e8a0b9d62\",\"text\":\"Précisez l\'ouverture ou la fuite constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"078cf50c-13a7-481e-baa5-1d82cf96c73e\",\"triggerValues\":[\"no\"]}},{\"id\":\"9217bb5b-0660-45e1-8448-322be147d032\",\"text\":\"L\'ouverture des portes du container ne révèle-t-elle aucune anomalie ou suspicion ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"aeefc288-7c77-4f6d-a4ea-41663f40ccb0\",\"text\":\"Précisez l\'anomalie ou la suspicion constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"9217bb5b-0660-45e1-8448-322be147d032\",\"triggerValues\":[\"no\"]}},{\"id\":\"aece6392-d291-41d8-b7e9-2e3e57b1c223\",\"text\":\"Le contrôle visuel initial confirme-t-il qu\'aucun carton ou sac n\'est ouvert ou endommagé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"56e87e18-8848-4746-b19b-fbb0b2929abb\",\"text\":\"Précisez les cartons/sacs ouverts ou endommagés constatés\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"aece6392-d291-41d8-b7e9-2e3e57b1c223\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"e04f622b-9850-4336-b7c2-227e7bd1b3ba\",\"label\":\"Opérations de déchargement et traçabilité\",\"questions\":[{\"id\":\"a1999769-7691-4360-9d99-138a335f16db\",\"text\":\"Le comptage contradictoire correspond-il au Packing List (et aux autres documents : facture, Bill of Lading) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"8a71deaa-3bdc-49d4-b69c-6bd0d0460393\",\"text\":\"Précisez l\'écart constaté (référence, quantité)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a1999769-7691-4360-9d99-138a335f16db\",\"triggerValues\":[\"no\"]}},{\"id\":\"3cbff0b2-0e01-4770-a8f1-7f87756819ee\",\"text\":\"Écart de quantité constaté (unités)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false,\"dependsOn\":{\"questionId\":\"a1999769-7691-4360-9d99-138a335f16db\",\"triggerValues\":[\"no\"]}},{\"id\":\"15f0dc14-2c53-4fd9-8d6e-edefdce6c12d\",\"text\":\"Le contrôle des DLC par échantillonnage est-il conforme ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"2158db26-b648-40ea-bb13-b63e87b4c1f8\",\"text\":\"Précisez les références et DLC non conformes constatées\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"15f0dc14-2c53-4fd9-8d6e-edefdce6c12d\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"b8483bcc-fc72-4efc-841b-1baa510b76ed\",\"label\":\"Procédure en cas de non-conformité\",\"questions\":[{\"id\":\"aec6c28b-751c-4837-bf28-da21b9e22c3a\",\"text\":\"Une non-conformité a-t-elle été détectée durant cet audit ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"053672e1-a3b3-4a94-a10e-ce988d9a985c\",\"text\":\"Description de la non-conformité constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"aec6c28b-751c-4837-bf28-da21b9e22c3a\",\"triggerValues\":[\"yes\"]}},{\"id\":\"eb68b44a-81af-45fd-830f-b0e109c04fdf\",\"text\":\"Des photographies horodatées ont-elles été prises (scellé cassé, marchandise endommagée, container peu rempli…) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"aec6c28b-751c-4837-bf28-da21b9e22c3a\",\"triggerValues\":[\"yes\"]}},{\"id\":\"1ea6c5ab-3359-4958-82cb-100b0230e32d\",\"text\":\"Le lot a-t-il été bloqué en zone de quarantaine (non-conformité majeure) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"aec6c28b-751c-4837-bf28-da21b9e22c3a\",\"triggerValues\":[\"yes\"]}},{\"id\":\"ed249e42-de13-478a-9b07-5074a9b48c29\",\"text\":\"Une fiche de non-conformité a-t-elle été émise et transmise à la Direction des Achats ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true,\"dependsOn\":{\"questionId\":\"aec6c28b-751c-4837-bf28-da21b9e22c3a\",\"triggerValues\":[\"yes\"]}}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T14:49:10.362Z','2026-10-21T14:49:10.362Z','container'),
('68c2311c-7ad0-441e-a277-1457c18aa71e','Audit logistique et commercial — Dépôt','Trame standard pour les audits dépôt : inventaire stock, clôture de caisse, facturation/livraison, retours clients, organisation et recouvrement. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"0baa4ee7-aee1-4462-9b97-ce382858e530\",\"label\":\"Inventaire stock dépôt\",\"questions\":[{\"id\":\"b5c41190-23b1-488e-9fc8-d1c3bcaaa5bc\",\"text\":\"Le stock physique correspond-il au stock système (PROXIM/PROMOFOOD/BEESKY) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"31cbf322-2f3a-43ec-8eba-9e5ea19c6208\",\"text\":\"Précisez la nature et la valeur de l\'écart constaté (article, quantité, montant)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"b5c41190-23b1-488e-9fc8-d1c3bcaaa5bc\",\"triggerValues\":[\"no\"]}},{\"id\":\"f34170e9-9c67-4465-ba17-0589d2c8f1ef\",\"text\":\"Des articles endommagés ou périmés ont-ils été identifiés ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"2a200e42-baeb-4b8a-a503-033e757efbe7\",\"text\":\"Détail des articles concernés et prix de liquidation proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"f34170e9-9c67-4465-ba17-0589d2c8f1ef\",\"triggerValues\":[\"yes\"]}},{\"id\":\"b5e54e8f-5e77-49e8-92a9-f441c2c287a9\",\"text\":\"Les mouvements de stock (transferts entre dépôts, gestes commerciaux) sont-ils tracés formellement ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"e36f7e3b-306d-433b-9637-67cc55ecd6af\",\"text\":\"Précisez les manques de traçabilité constatés\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"b5e54e8f-5e77-49e8-92a9-f441c2c287a9\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"d5f24d96-3902-415c-bcbe-d71c43a64d66\",\"label\":\"Clôture de caisse et inventaire véhicule (agents commerciaux)\",\"questions\":[{\"id\":\"61b3ec27-966e-44b1-8596-1be73ec50fd7\",\"text\":\"Un écart a-t-il été constaté entre le système (NOMADIS) et les espèces encaissées ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"b255a602-673c-403e-a3fe-fa29a6f09213\",\"text\":\"Montant de l\'écart constaté (DT)\",\"type\":\"NUMBER\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"61b3ec27-966e-44b1-8596-1be73ec50fd7\",\"triggerValues\":[\"yes\"]}},{\"id\":\"881ecfac-9a02-41ea-9a5a-89cf3f8cab4d\",\"text\":\"Un justificatif a-t-il été présenté par l\'agent ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"61b3ec27-966e-44b1-8596-1be73ec50fd7\",\"triggerValues\":[\"yes\"]}},{\"id\":\"a235eab8-0759-43f3-bd97-fcd86e5ab434\",\"text\":\"L\'écart a-t-il été régularisé immédiatement ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"61b3ec27-966e-44b1-8596-1be73ec50fd7\",\"triggerValues\":[\"yes\"]}},{\"id\":\"b3ca4cec-991a-4e01-81a5-e7e30e55c325\",\"text\":\"Un écart a-t-il été constaté lors de l\'inventaire du stock véhicule ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"cae22479-6cd3-4c5c-9121-ad1e22a0dec1\",\"text\":\"Montant/quantité de l\'écart et régularisation effectuée\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"b3ca4cec-991a-4e01-81a5-e7e30e55c325\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"649b42ab-d15e-4031-ad10-405efe364d67\",\"label\":\"Facturation, livraison et retours clients\",\"questions\":[{\"id\":\"5a694d48-5a09-4f27-adbb-ef202795cc5a\",\"text\":\"Les livraisons sont-elles systématiquement facturées avant sortie de marchandise ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"d004989b-6785-475e-b218-1e00632fb4d2\",\"text\":\"Précisez les cas de livraison sans facturation préalable et la régularisation effectuée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"5a694d48-5a09-4f27-adbb-ef202795cc5a\",\"triggerValues\":[\"rarel